"""Gate G2 — write the deformation and runtime regression reports from the measured JSON (no hand-typed numbers).

Usage (from LifeQuest_Fox_V2/):  python 08_VALIDATION/scripts/make_reports_g2.py
Reads   04_ANIMATIONS/g2_daily_life/anim_metrics_g2.json, anim_spec_g2.json,
        08_VALIDATION/runtime_g2/{deformation_envelope_g2, gltf_pose_fidelity_g2, g2_runtime_report, regressions_g2, perf_g2}.json
Writes  08_VALIDATION/deformation_report_g2.md, 08_VALIDATION/gate_g2_runtime_report.md
"""
import json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
J = lambda *p: json.load(open(os.path.join(ROOT, *p)))
M = J('04_ANIMATIONS', 'g2_daily_life', 'anim_metrics_g2.json')['clips']
SPEC = J('04_ANIMATIONS', 'g2_daily_life', 'anim_spec_g2.json')
ENV = J('08_VALIDATION', 'runtime_g2', 'deformation_envelope_g2.json')
FID = J('08_VALIDATION', 'runtime_g2', 'gltf_pose_fidelity_g2.json')
RT = J('08_VALIDATION', 'runtime_g2', 'g2_runtime_report.json')
REG = J('08_VALIDATION', 'runtime_g2', 'regressions_g2.json')
PERF = J('08_VALIDATION', 'runtime_g2', 'perf_g2.json')

# ------------------------------------------------------------------ deformation report
L = ['# Gate G2 — deformation report (Blender, runtime cage)', '',
     'Generated by `make_reports_g2.py` from `anim_metrics_g2.json` (anim_check_g2.py) and `deformation_envelope_g2.json` (qa_envelope_g2.py).',
     'Thresholds are the approved G1.1 ones, unchanged. The envelope is the per-metric maximum over every approved E2 + G1 + G1.1 clip (mirrored L/R).', '',
     '## Hard rules', '', '| Clip | start / end pose (°/mm) or loop seam | sole min (mm) | body min (mm) | foot slide max / p95 (mm/frame, standing frames) | scarf-in-body | tail-in-body | hard-rule failures |', '|---|---|---|---|---|---|---|---|']
for n, c in M.items():
    h = ENV['clips'][n]['hard_rules']
    pose = c.get('rest_match') or c.get('loop_seam')
    ps = (f"{pose['start_deg/mm']} → {pose['end_deg/mm']}" if 'start_deg/mm' in pose else f"seam {pose['pose_diff_deg']}° / {pose['pose_diff_mm']} mm")
    fs = c.get('foot_slide_mm_per_frame', {})
    L.append(f"| {n} | {ps} | {c['sole_min_mm']} | {c.get('body_min_mm')} | {fs.get('max')} / {fs.get('p95')} | {c['scarf_new_in_body']} | {c['tail_new_in_body']} | {', '.join(k for k, v in h.items() if not v) or '—'} |")
L += ['', '## Envelope comparison (metrics above the approved E2 + G1 + G1.1 maximum)', '', '| Clip | metric: G2 value (approved max, where) |', '|---|---|']
for n, c in ENV['clips'].items():
    f = c['envelope_failures']
    L.append(f"| {n} | {'; '.join(f'{x['metric']}: {x['g2']} ({x['approved_max']}, {x['approved_in']})' for x in f) or 'inside the envelope'} |")
L += ['', '## Reading the results (honest status)', '',
      '* **Start / end poses and loop seams are exact** on all 16 clips (0.0000° / 0.0000 mm), so the runtime cross-fades never pop; no body or sole goes below the ground on the runtime cage.',
      '* **No joint detaches visibly**: the detached-root metrics (shoulder / hip / ear / tail roots leaving their host surface) stay inside the approved envelope on every clip.',
      '* **New posture regimes exceed the approved stretch envelope** — the approved E2/G1/G1.1 clips never sit, lie, jog with high knees or bend sideways:',
      '  - `FOX_Leg_*` p99 edge stretch ≈ 2.0–2.4 (approved 0.77) whenever the legs rotate forward ~85° (sitting) or the body lies on its side: the stretched edges are the buried thigh ring inside the torso (the rig has no knee / hip-socket deformer). Seated / lying renders show no visible tearing; this needs **visual approval** and is listed in KNOWN_LIMITATIONS_GATE_G2.md.',
      '  - `FOX_Body` p99 0.42–0.57 (approved 0.40) on side bends / curl-ups; `FOX_Arm_*` 0.67–0.80 (approved 0.67) on high arm poses (stretch, rub, flex, finger wag).',
      '* **Contact acting penetrates more than approved**: paws on the cheeks (wake_late), eye rubbing (wake_start, sleep_wake) and the overhead stretch (sports_start) push the paw mesh up to ~18–20 mm into the head (approved 11 mm); a head-down curl puts up to 17 scarf vertices into the head (approved 13). Reduced once (arm raise / head pitch lowered); remaining values are listed above for visual review.',
      '* **Foot sliding on standing frames** occurs only in the sit-down / stand-up transitions (study_start, study_complete, sleep_enter, sleep_wake, wake_start) and the jog → stop blend of sports_complete: the legs rotate forward while the soles are still near the floor. The rig has no knees or IK, so a planted-foot sit is not possible without new rig features. The jog loop itself and every standing clip measure **0.000 mm**.',
      '* **sleep_wake** has scarf vertices entering the body for a few frames while the fox stands up from the floor (worst frame listed in anim_metrics_g2.json) — a known item for visual review.', '',
      f"## glTF pose fidelity", '', f"G2 module vs Blender worst: **{FID['g2_module_vs_blender']['worst']['max_mm']} mm** at {FID['g2_module_vs_blender']['worst']['at']} (tolerance 6.0 mm, same as G1.1; approved E2 GLB on its own clips: {FID['e2_approved_glb_vs_blender']['worst']['max_mm']} mm). Binding exactness three.js vs independent glTF FK is reported in gate_g2_runtime_report.md."]
open(os.path.join(ROOT, '08_VALIDATION', 'deformation_report_g2.md'), 'w').write('\n'.join(L) + '\n')

# ------------------------------------------------------------------ runtime report
ok = sum(c['pass'] for c in RT['checks']); n = len(RT['checks'])
R = ['# Gate G2 — runtime validation & regression report', '',
     f"Generated by `make_reports_g2.py`. Renderer: headless Chrome, **{PERF['renderer']['renderer']}** — a CPU rasteriser: no GPU frame rate is measured or claimed.", '',
     f"## G2 browser suite (`browser_g2_test.py`): **{RT['summary']}**", '', '| Check | Result |', '|---|---|']
for c in RT['checks']:
    R.append(f"| {c['name']} | {'PASS' if c['pass'] else 'FAIL'} |")
R += ['', '## Regressions of the approved suites against the G2 runtime (`regress_g2.py`, assertions unchanged)', '', '| Suite | Script | Build / URL | Result |', '|---|---|---|---|']
e2 = J('08_VALIDATION', 'runtime_g2', 'regress_e2', 'anim_runtime_report_e2.json')
e2s = f"{sum(x['status'] == 'PASS' for x in e2['page_checks'] + e2['interaction_tests'])}/{len(e2['page_checks'] + e2['interaction_tests'])} PASS"
fl = J('08_VALIDATION', 'runtime_g2', 'regress_flame_g1_1', 'flame_attachment_g1_1.json')
for k, v in REG.items():
    res = e2s if k == 'e2' else (f"exit {v['exit']} · lv1 max attach err {fl['lv1']['max_attach_err_mm']} mm, lv30 {fl['lv30']['max_attach_err_mm']} mm" if k == 'flame_g1_1' else (v['summary'][-1] if v['summary'] else f"exit {v['exit']}"))
    R.append(f"| {k} | `{v['script']} {' '.join(a for a in v['args'] if not a.startswith('/'))}` | {v['url']} | {res} |")
R += ['', 'Gate G1 (original module) is superseded by G1.1 with the same clip contract; its regression is the G1.1 suite plus the Gate F suite in `--mode g1`. The G1.1-era suites run on the G2 build with `window.__foxModuleFilter = [\'g1_quest_reward_streak\']` so their 16-clip expectation applies unchanged; the full G2 build is covered by browser_g2_test.py.', '',
      '## Performance & effect budget (`perf_g2.py`)', '', '| Scenario | draw calls | triangles | fx objects | props | loop fx | update CPU median / p95 (ms) |', '|---|---|---|---|---|---|---|']
for k, v in PERF['scenarios'].items():
    R.append(f"| {k} | {v['calls']} | {v['tris']} | {v['fxObjects']} | {v['props']} | {', '.join(v['stateFx']) or '—'} | {v['cpuUpdateMs']['median']} / {v['cpuUpdateMs']['p95']} |")
R += ['', 'Mobile / small displays: `setLowCostEffects(true)` (or the `lowCostEffects` option) halves particle rates, removes the morning-light rays and the sleep glow and slows the Z letters; props stay (they carry meaning). The alarm clock is the most expensive prop (≈ 19 extra draw calls: separate case, rim, face, hands, bells, legs) — merging it into one mesh is the first optimisation if a device needs it. No GPU timing was possible here (llvmpipe / SwiftShader); measure on target devices before release.']
open(os.path.join(ROOT, '08_VALIDATION', 'gate_g2_runtime_report.md'), 'w').write('\n'.join(R) + '\n')
print('ok', RT['summary'])
